        ZipProgressListener* listener = *it;
        int cancelled;
        try {
            cancelled = listener->cancel();
        } catch (...) {
            //a throwing cancel() aborts the commit like a regular cancellation
            dispatch->exception = std::current_exception();
            return 1;
        }
        if (cancelled)
          return 1;
    }
    return 0;
